import { ReleaseTimeline, type TimelineEvent } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function captures(fn: () => void): unknown {
  try { fn(); } catch (error) { return error; }
  return undefined;
}

const timeline = new ReleaseTimeline();
const observed: TimelineEvent[] = [];
const order: string[] = [];
let unsubscribeSecond = (): void => {};
timeline.subscribe(event => {
  order.push(`first:${event.kind}`);
  observed.push(event);
  unsubscribeSecond();
});
unsubscribeSecond = timeline.subscribe(event => order.push(`second:${event.kind}`));

const first = timeline.append('  One  ');
deepEqual(first, { id: 1, label: 'One', note: null }, 'append trims label and defaults note');
deepEqual(order, ['first:added', 'second:added'], 'listeners use notification-start subscription snapshot');
unsubscribeSecond();
first.label = 'Changed';
observed[0].entry.label = 'Event mutation';
assert(timeline.snapshot()[0].label === 'One', 'returns and events cannot mutate state');

const second = timeline.append('Two', ' note unchanged ');
deepEqual(second, { id: 2, label: 'Two', note: ' note unchanged ' }, 'supplied note preserved');
deepEqual(order, ['first:added', 'second:added', 'first:added'], 'unsubscribe is idempotent and affects later events');
const renamed = timeline.rename(2, '  Second  ');
deepEqual(renamed, { id: 2, label: 'Second', note: ' note unchanged ' }, 'rename succeeds');
const promoted = timeline.promote(2);
assert(promoted.id === 2, 'promotion returns entry');
deepEqual(timeline.snapshot().map(entry => entry.id), [2, 1], 'promotion moves item to front');
timeline.promote(2);
deepEqual(timeline.snapshot().map(entry => entry.id), [2, 1], 'promoting first item succeeds without reordering others');

const snapshot = timeline.snapshot();
snapshot.reverse();
snapshot[0].label = 'Bad';
deepEqual(timeline.snapshot().map(entry => entry.label), ['Second', 'One'], 'snapshot is defensive');
assert(timeline.remove(999) === false, 'absent removal returns false');
assert(timeline.remove(1) === true, 'existing removal succeeds');
assert(timeline.append('Three').id === 3, 'ids are never reused');

const beforeFailed = timeline.snapshot();
assert(captures(() => timeline.append('   ')) instanceof TypeError, 'blank label rejected');
assert(captures(() => timeline.append('X', 4 as unknown as string)) instanceof TypeError, 'non-string note rejected');
for (const id of [0, -1, 1.5, NaN]) {
  assert(captures(() => timeline.rename(id, 'X')) instanceof RangeError, 'rename id validated');
  assert(captures(() => timeline.remove(id)) instanceof RangeError, 'remove id validated');
  assert(captures(() => timeline.promote(id)) instanceof RangeError, 'promote id validated');
}
assert(captures(() => timeline.rename(999, 'X')) instanceof RangeError, 'rename absent id rejected');
assert(captures(() => timeline.promote(999)) instanceof RangeError, 'promote absent id rejected');
deepEqual(timeline.snapshot(), beforeFailed, 'failed operations do not mutate state');

const exceptional = new ReleaseTimeline();
const delivered: string[] = [];
exceptional.subscribe(() => { delivered.push('throwing'); throw new Error('listener failed'); });
exceptional.subscribe(() => delivered.push('later'));
const listenerError = captures(() => exceptional.append('Persisted'));
assert(listenerError instanceof Error && (listenerError as Error).message === 'listener failed', 'listener exception propagates');
deepEqual(delivered, ['throwing'], 'listener exception stops later delivery');
assert(exceptional.snapshot().length === 1, 'mutation remains committed when listener throws');

